"use client";
import {useEffect,useState} from "react";
import {Boot} from "@/components/Boot";
import {Desktop} from "@/components/Desktop";
import {Recruiter} from "@/components/Recruiter";
export default function Home(){const [state,setState]=useState<"loading"|"boot"|"desktop"|"recruiter"|"recovery">("loading");const [initial,setInitial]=useState<string>();useEffect(()=>setState(localStorage.getItem("amssec-booted")==="true"?"desktop":"boot"),[]);const done=(mode="desktop")=>{localStorage.setItem("amssec-booted","true");if(mode==="recruiter")setState("recruiter");else if(mode==="recovery")setState("recovery");else {setInitial(mode==="labs"?"labs":undefined);setState("desktop")}};if(state==="loading")return <main className="loading">Mounting AMS-sec environment…</main>;if(state==="boot")return <Boot onComplete={done}/>;if(state==="recruiter")return <Recruiter back={()=>setState("desktop")}/>;if(state==="recovery")return <main className="recovery"><pre>Running career recovery...{`\n\n`}Checking certifications ........ [ OK ]{`\n`}Checking cybersecurity labs .... [ OK ]{`\n`}Checking leadership ............ [ OK ]{`\n`}Checking GitHub activity ....... [ OK ]{`\n\n`}Searching job market...{`\n\n`}Suggested action:{`\n`}contact --operator almas</pre><button onClick={()=>setState("desktop")}>Return to desktop</button></main>;return <Desktop initialApp={initial} goRecruiter={()=>setState("recruiter")} restart={()=>{localStorage.removeItem("amssec-booted");setState("boot")}}/>}

